"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import { motion } from "framer-motion";
import axios from "axios";

export default function UserCartPage() {
  const [cart, setCart] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRou

  // ✅ FETCH CART
  const getCart = async () => {
    try {
      const res = await axios.get("/api/cart/get");
      if (res.status === 200) {
        setCart(res.data.cart || []);
      }
    } catch (error) {
      console.log("Cart fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    getCart();
  }, []);

  // ✅ REMOVE FROM CART (Optimistic)
  const handleRemoveFromCart = async (productId: string) => {
    setCart((prev) =>
      prev.filter(
        (item) =>
          item.product._id.toString() !== productId.toString()
      )
    );

    try {
      await axios.post("/api/cart/remove", { productId });
    } catch (err) {
      alert("Remove failed, refreshing cart ❌");
      getCart();
    }
  };

  // ✅ UPDATE QUANTITY
  const handleUpdateQuantity = async (
    productId: string,
    newQty: number
  ) => {
    if (newQty < 1) return;

    setCart((prev) =>
      prev.map((item) =>
        item.product._id.toString() === productId.toString()
          ? { ...item, quantity: newQty }
          : item
      )
    );

    try {
      const res = await axios.post("/api/cart/update", {
        productId,
        quantity: newQty,
      });

      if (res.status !== 200) throw new Error();
    } catch {
      alert("Quantity update failed ❌");
      getCart();
    }
  };
// ✅ PRODUCT TOTAL
const productsTotal = cart.reduce(
  (sum, item) => sum + item.product.price * item.quantity,
  0
);

// ✅ DELIVERY CHARGE CALCULATION
const nonFreeDeliveryCount = cart.filter(
  (item) => item.product.freeDelivery === false
).length;

const deliveryCharge = nonFreeDeliveryCount * 50;

// ✅ SERVICE CHARGE (ONCE)
const serviceCharge = cart.length > 0 ? 30 : 0;

// ✅ FINAL TOTAL
const finalTotal =
  productsTotal + deliveryCharge + serviceCharge;


  const handleCheckout = () => {
  router.push(`/checkout?amount=${finalTotal}`);
};


  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center text-white">
        Loading cart...
      </div>
    );
  }

  if (cart.length === 0) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-black to-gray-900 flex flex-col items-center justify-center text-white">
        <h2 className="text-2xl font-bold mb-2">
          Your Cart is Empty 🛒
        </h2>
        <p className="text-gray-400">
          Add some products to continue shopping.
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-black to-gray-900 text-white p-6">
      <div className="max-w-6xl mx-auto">

        {/* ✅ PAGE HEADER */}
        <motion.div
          initial={{ opacity: 0, y: -30 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-6"
        >
          <h1 className="text-3xl font-bold">Your Shopping Cart</h1>
          <p className="text-gray-400 text-sm">
            Review your selected items before checkout
          </p>
        </motion.div>

        <div className="grid md:grid-cols-3 gap-6">

          {/* ✅ CART ITEMS */}
          <div className="md:col-span-2 space-y-4">
            {cart.map((item, i) => (
              <motion.div
                key={item.product._id}
                initial={{ opacity: 0, y: 40 }}
                animate={{ opacity: 1, y: 0 }}
                whileHover={{ scale: 1.01 }}
                transition={{ delay: i * 0.05 }}
                className="bg-white/10 border border-white/20 rounded-xl p-4 flex gap-4"
              >
                {/* IMAGE */}
                <div className="relative w-24 h-24 bg-white rounded-lg overflow-hidden">
                  <Image
                    src={item.product.image1}
                    alt={item.product.title}
                    fill
                    className="object-contain p-1"
                  />
                </div>

                {/* DETAILS */}
                <div className="flex-1">
                  <h3 className="font-semibold">
                    {item.product.title}
                  </h3>
                  <p className="text-xs text-gray-400">
                    {item.product.category}
                  </p>
                  <p className="text-green-400 font-bold mt-1">
                    ₹ {item.product.price}
                  </p>

                  {/* ✅ QUANTITY CONTROLS */}
                  <div className="flex items-center gap-2 mt-2">
                    <motion.button
                      whileTap={{ scale: 0.9 }}
                      onClick={() =>
                        handleUpdateQuantity(
                          item.product._id,
                          item.quantity - 1
                        )
                      }
                      disabled={item.quantity <= 1}
                      className="px-2 py-1 bg-white/20 rounded disabled:opacity-40"
                    >
                      −
                    </motion.button>

                    <span className="px-3 py-1 border rounded">
                      {item.quantity}
                    </span>

                    <motion.button
                      whileTap={{ scale: 0.9 }}
                      onClick={() =>
                        handleUpdateQuantity(
                          item.product._id,
                          item.quantity + 1
                        )
                      }
                      className="px-2 py-1 bg-white/20 rounded"
                    >
                      +
                    </motion.button>
                  </div>

                  {/* ✅ REMOVE BUTTON */}
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.9 }}
                    onClick={() =>
                      handleRemoveFromCart(item.product._id)
                    }
                    className="mt-2 text-xs text-red-400 hover:text-red-500 underline"
                  >
                    Remove
                  </motion.button>
                </div>

                {/* ITEM TOTAL */}
                <div className="font-bold text-green-400">
                  ₹ {item.product.price * item.quantity}
                </div>
              </motion.div>
            ))}
          </div>

          {/* ✅ SUMMARY */}
          <motion.div
  initial={{ opacity: 0, x: 40 }}
  animate={{ opacity: 1, x: 0 }}
  className="bg-white/10 border border-white/20 rounded-xl p-5 h-fit space-y-4"
>
  <h2 className="text-xl font-bold">Cart Summary</h2>

  <div className="flex justify-between text-sm">
    <span>Products Total</span>
    <span>₹ {productsTotal}</span>
  </div>

  <div className="flex justify-between text-sm">
    <span>Delivery Charges</span>
    <span className="text-yellow-400">
      ₹ {deliveryCharge}
    </span>
  </div>

  <div className="flex justify-between text-sm">
    <span>Service Charge</span>
    <span className="text-yellow-400">
      ₹ {serviceCharge}
    </span>
  </div>

  <div className="flex justify-between text-lg font-bold border-t pt-3 mt-3">
    <span>Final Amount</span>
    <span className="text-green-400">
      ₹ {finalTotal}
    </span>
  </div>

  <motion.button
    whileHover={{ scale: 1.03 }}
    whileTap={{ scale: 0.95 }}
    className="w-full bg-blue-600 hover:bg-blue-700 py-3 rounded-lg font-semibold transition"
  >
    Proceed to Checkout
  </motion.button>
</motion.div>


        </div>
      </div>
    </div>
  );
}
